def caesar_cipher(text: str, shift: int) -> str:
    result = []
    shift_mod = shift % 26
    for ch in text:
        if 'a' <= ch <= 'z':
            start = ord('a')
            result.append(chr(start + (ord(ch) - start + shift_mod) % 26))
        elif 'A' <= ch <= 'Z':
            start = ord('A')
            result.append(chr(start + (ord(ch) - start + shift_mod) % 26))
        else:
            result.append(ch)
    return ''.join(result)

